package com.nexbank.account.service;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Component public class OutboxPublisher {private final JdbcTemplate jdbc;private final KafkaTemplate<String,String> kafka;public OutboxPublisher(JdbcTemplate jdbc,KafkaTemplate<String,String> kafka){this.jdbc=jdbc;this.kafka=kafka;}
 @Scheduled(fixedDelayString="${OUTBOX_POLL_MS:1000}") @Transactional public void publish(){List<Map<String,Object>> batch=jdbc.queryForList("select id,aggregate_id,event_type,payload::text as payload from outbox_events where published=false order by created_at limit 50 for update skip locked");for(Map<String,Object> row:batch){String eventType=(String)row.get("event_type");String key=row.get("aggregate_id").toString();String payload=(String)row.get("payload");try{kafka.send(eventType,key,payload).get();jdbc.update("update outbox_events set published=true where id=?",row.get("id"));}catch(Exception e){throw new IllegalStateException("Outbox publish failed; event will be retried",e);}}}
}
